(() => {
  'use strict';
  const root = document.getElementById('cases');
  if (!root) return;
  const $ = (id) => root.querySelector(`#case-${id}`);
  const step = (title, layer, actor, kind, description, call, observation, next, source) => ({ title, layer, actor, kind, description, call, observation, next, source });
  const S = step;
  const searchUpload = S('Locate the uploaded sources', 'model', 'MODEL → TOOL', 'REGISTERED TOOL', 'The current question concerns uploaded material, so the prompt directs the model to workspace_search before directory scans or full-file reads.', 'workspace_search({\n  query: "material for the requested report",\n  limit: 8\n})', 'Candidate records include current path, original filename aliases, text_path, document_type, and a reader hint.', 'Choose a returned sidecar to read. Use a format-specific reader only if the requested detail is absent from extracted text.', 'runner.py:861–901,2340–2343 · workspace_search');
  const readUpload = S('Read selected evidence', 'disk', 'MODEL → FILE TOOL', 'FRAMEWORK TOOL', 'The model requests the returned text_path. The filesystem middleware resolves the virtual path to the current thread’s disk workspace.', 'read_file({\n  file_path: "/workspace/source.docx.md"\n})', 'The result contains extracted text. It is neither an instruction from the user nor the original Word document’s complete rendering.', 'Use the relevant text to draft. If a table or layout detail is missing, choose its specialized reader.', 'runner.py:2584–2595 · CompositeBackend; FilesystemMiddleware');
  const planReport = S('Write the report in parts', 'state', 'MODEL → FILE TOOL', 'GRAPH-STATE FILE', 'The prompt asks the orchestrator to keep plans and long report chapters at root paths. The framework routes these paths to StateBackend.', 'write_file({\n  file_path: "/chapter_1.md",\n  content: "# Evidence summary\\n…"\n})', 'A chapter is represented in graph state. This path is not the same storage as /workspace/chapter_1.md.', 'Write further chapters as needed, then compose the final report. The model selects how many parts the request needs.', 'runner.py:2327–2331,2584–2595');
  const finalReport = S('Compose the final Markdown', 'state', 'MODEL → FILE TOOL', 'GRAPH-STATE FILE', 'The model writes the deliverable using the generated chapters and source content. File state becomes visible through the SDK.', 'write_file({\n  file_path: "/final_report.md",\n  content: "# Report\\n…"\n})', 'stream.values.files contains the file representation; messages and todo updates can arrive separately.', 'The user can inspect or edit the Markdown and choose an export format. Writing a file does not itself call a converter.', 'runner.py:2327–2331; useChat.ts:134–158,336–343');
  const requestExport = S('User chooses PDF export', 'ui', 'USER → UI ROUTE', 'NOT AN LLM TOOL', 'The file viewer submits its current content and chosen format to a separate Next.js route. The model does not call /api/export.', 'POST /api/export\n{\n  "fileName": "final_report.md",\n  "format": "pdf",\n  "content": "# Report\\n…"\n}', 'The route receives browser-provided text, normalizes the format, and invokes createExportFile. It does not fetch a protected artifact by ID.', 'The server performs conversion. A successful result is returned as download bytes; a converter failure is surfaced to the user.', 'FileViewDialog.tsx:98–110; utils/audit.ts:20–49; api/export/route.ts:30–81');
  const exportSuccess = S('Convert and return bytes', 'service', 'SERVER → CONVERTER', 'DETERMINISTIC SERVICE', 'The exporter writes a temporary Markdown file, runs Pandoc, reads the output, and removes the temporary directory. PDF uses XeLaTeX or Tectonic with configured fonts.', 'createExportFile("pdf", markdown)\n  → temporary input.md\n  → Pandoc + selected PDF engine\n  → application/pdf + attachment', 'The browser receives a PDF download. DOCX follows the same export service; Markdown export returns the text directly.', 'The user reviews the downloaded result. Export is a separate lifecycle from the completed model run.', 'exporters.ts:182–257; api/export/route.ts:63–81');
  const exportFailure = S('Conversion reports a failure', 'output', 'CONVERTER → UI', 'ERROR RESPONSE', 'A missing PDF engine, font issue, timeout, or Pandoc failure returns a structured export error. This is not a new model observation.', 'HTTP 500\n{ "error_code": "pdf_engine_not_available",\n  "error": "PDF conversion engine unavailable" }\n// Example message translated for this exhibit.', 'The source Markdown remains in the file view. No PDF bytes are returned, and no model retry is triggered by this UI route.', 'The user can download Markdown, choose another available export format, or retry after the converter dependency is repaired.', 'exporters.ts:196–207; api/export/route.ts:82–104');
  const uploadWord = S('Upload the original Word file', 'ui', 'USER → UI ROUTE', 'MULTIPART UPLOAD', 'A user selects a document. The UI route first resolves the department and browser-owned thread workspace before writing the uploaded bytes.', 'POST /api/workspace\nContent-Type: multipart/form-data\nfile: draft.docx\n// Thread context travels in the workspace header.', 'The original binary goes to the thread’s physical disk directory. The route returns its final path, processing status, and indexing metadata.', 'The upload service starts extraction and indexing before the next agent question. The binary is not copied into the model prompt.', 'api/workspace/route.ts:69–151; workspaceContext.ts:11–53');
  const indexWord = S('Extract and index once', 'disk', 'UPLOAD SERVICE → DISK', 'DETERMINISTIC PREPROCESSING', 'python-docx extracts paragraphs and tables into an adjacent Markdown sidecar. A compact index derives title, summary, keywords, aliases, and the current file path.', 'draft.docx\n  → python-docx\n  → draft.docx.md + compact metadata\n  → optional semantic filename', 'The stored name can change after indexing. Later tool calls should use returned paths or search aliases, not assume the original filename is the current path.', 'On the next question, search the index first. Read the text sidecar for content; choose word_reader for detailed blocks and formatting.', 'workspace_index.py:251–289,572–601,661–674');
  const wordSearch = S('Choose the document by topic', 'model', 'MODEL → TOOL', 'REGISTERED TOOL', 'The request asks about a Word document. Search narrows candidates by topic and format using metadata, not a whole-corpus embedding search.', 'workspace_search({\n  query: "review the uploaded draft",\n  document_types: ["word"],\n  limit: 8\n})', 'A returned candidate names the original or renamed file and its text_path. That gives the next call a concrete path.', 'For a summary, read the sidecar. For block-level formatting or table structure, select word_reader instead.', 'runner.py:862–884,2340–2343');
  const wordDetails = S('Request block-level detail', 'disk', 'MODEL → TOOL', 'SPECIALIZED READER', 'The model needs paragraphs, runs, or table structure that the ordinary sidecar view does not preserve.', 'word_reader({\n  virtual_docx_path: "/workspace/draft.docx",\n  max_blocks: 200\n})', 'The result includes blocks, formatting metadata, Markdown, blocks_returned, and truncated. The original document is unchanged.', 'If truncated is true and the full document is required, the model may make another call with a different max_blocks value.', 'runner.py:1003–1042,1398–1405');
  const wordRetry = S('Revise the reader argument', 'model', 'MODEL → TOOL', 'OBSERVATION-DRIVEN CHOICE', 'The preceding result reported truncated:true. This example changes the reader limit; there is no hardcoded workflow that automatically retries every truncated result.', 'word_reader({\n  virtual_docx_path: "/workspace/draft.docx",\n  max_blocks: 0\n})\n// 0 disables this reader’s block limit.', 'The tool can return the complete block set. Model context capacity remains finite, so a large response still needs careful handling.', 'Generate a summary or new Markdown revision. Exporting that revision as DOCX is a separate user action; tracked edits to the original are not implemented here.', 'runner.py:1028–1029; Word reader result contract');
  const voiceInput = S('Record or attach dictation', 'ui', 'USER → UI ROUTE', 'NOT AN LLM TOOL', 'The chat input collects an audio blob with MediaRecorder or a selected audio file, then posts it to the voice-input route.', 'POST /api/asr\nContent-Type: multipart/form-data\naudio: voice-input.webm', 'The route checks origin and department entry, limits input size, and writes temporary audio. This does not yet submit an agent message.', 'The ASR service must produce text before the user can review and send it.', 'ChatInterface.tsx:191–240,293–314; api/asr/route.ts:34–95');
  const voiceASR = S('Return a transcript', 'service', 'ASR SERVICE → UI', 'VOICE-INPUT RESPONSE', 'The server runs audio normalization / transcription through ensureAudioTextSidecar and returns the resulting text. Temporary files are removed.', '{\n  "ok": true,\n  "text": "Please summarize my uploaded notes.",\n  "language": "en"\n}\n// Illustrative response fields; sample transcript.', 'ChatInterface appends the transcript to the editable input field. It does not silently call sendMessage.', 'The user corrects the words and presses Send. The resulting human message follows the ordinary agent path.', 'api/asr/route.ts:88–145; ChatInterface.tsx:226–233');
  const voiceSubmit = S('Send reviewed text', 'ui', 'USER → SDK', 'AGENT COMMAND', 'The same text composer used for typed requests sends a human message. The LLM sees the reviewed transcript, not this temporary microphone recording.', 'stream.submit({\n  messages: [{\n    id: "message_example",\n    type: "human",\n    content: "Please summarize my uploaded notes."\n  }]\n})', 'The SDK creates or uses the thread and begins a run. Tool selection now depends on what the submitted text asks for.', 'For uploaded notes, the model can choose workspace_search and then read a returned sidecar.', 'useChat.ts:171–194');
  const meetingRead = S('Read the meeting transcript', 'model', 'MODEL → TOOL', 'REGISTERED TOOLS', 'For a stored meeting recording, search the workspace first. Prefer its generated transcript sidecar. Invoke audio_transcribe when transcription or audio-specific detail is still needed.', 'workspace_search({query: "meeting recording"})\n\n// If ASR is still needed:\naudio_transcribe({\n  virtual_audio_path: "/workspace/meeting.m4a"\n})', 'audio_transcribe returns text, segments, language, chunk_count, and a text_path sidecar, or an error payload.', 'After ASR, the prompt directs the orchestrator to delegate text refinement and meeting minutes to the named subagent.', 'runner.py:1418–1461,2340–2343,2366–2369');
  const meetingDelegate = S('Delegate text refinement', 'model', 'ORCHESTRATOR → SUBAGENT', 'FRAMEWORK TASK TOOL', 'The explicit transcription subagent receives text for cleanup and minutes. The orchestration prompt keeps audio processing and file work with the parent agent.', 'task({\n  subagent_type: "transcription-processing-agent",\n  description: "Refine the supplied transcript and produce structured minutes without inventing facts. …"\n})', 'The subagent produces a refined transcript and meeting sections: goals, discussion, conclusions, constraints, actions, and open questions.', 'The orchestrator can return the text or write a report. The subagent inherits framework middleware; prompt instructions are not a separate permission sandbox.', 'runner.py:2372–2457; installed Deep Agents SubAgentMiddleware');
  const dataMeta = S('Discover fields first', 'model', 'MODEL → TOOL', 'REGISTERED DATA TOOL', 'For the local dataset service, the model can inspect metadata before constructing a filter or aggregate. This avoids inventing field names.', 'dataset_api_meta()', 'Metadata describes the available dataset keys and entry count. This adapter talks to a fixture-backed HTTP data service in the source project.', 'Choose search for individual records, or aggregate for exact counts and numeric summaries.', 'runner.py:1966–2009,2363–2364');
  const dataAggregate = S('Choose aggregation, not sampling', 'model', 'MODEL → TOOL', 'REGISTERED DATA TOOL', 'The request asks for a total. The prompt prefers the aggregate endpoint rather than estimating from a page of search results.', 'dataset_api_aggregate({\n  metrics: [{op: "count", as: "records"}],\n  filters: {}\n})', 'The adapter POSTs to the dataset aggregate endpoint and returns its JSON result or an error payload. No direct SQL string is executed by this tool.', 'Interpret the returned aggregate. If the service rejects a field or filter, inspect metadata and revise arguments instead of inventing a result.', 'runner.py:2086–2160');
  const apiChoose = S('Select a business connector', 'model', 'MODEL → TOOL', 'DISPLAY ALIAS', 'The model selects the registered business-query tool for an operations question. The source also exposes a catalog and a direct code-and-filter query.', 'connector.smart_query({\n  question: "查询指定设备的维修记录"\n})\n// Public display alias for the registered adapter.', 'The adapter has a catalog of supported business queries. It does not create a new API or execute arbitrary model-generated code.', 'The adapter resolves the closest supported query and extracts filters; unsupported questions return a structured failure.', 'runner.py:2164–2289; connector adapter · run_smart_query');
  const apiRoute = S('Resolve catalog + filters', 'service', 'CONNECTOR ADAPTER', 'DETERMINISTIC ROUTING', 'Inside this tool, keyword and sample-question scores select a catalog entry. Explicit filters override inferred filters; this inner routing is code, not another LLM call.', 'catalog.select(question)\n  → infer_filters(question, api)\n  → {...inferred, ...explicitFilters}\n  → run_api_query(...)', 'The query receives a defined schema and bounded pagination parameters. A nonmatching question has no selected API.', 'Call the selected connector. If there is no match, return the failure so the model can inspect the catalog or ask the user to narrow the request.', 'connector adapter · catalog.select:59–80, run_smart_query:444–478');
  const apiResult = S('Normalize a bounded result', 'service', 'CONNECTOR → MODEL', 'TOOL OBSERVATION', 'The adapter translates known fields, omits empty values, and summarizes returned records. Pagination ends on a short/empty page or the configured cap.', 'Result fields:\nsuccess · record_count · translated_records\nsummary · pages_fetched · returned_record_limit\nerror_message', 'The normal return exposes up to 20 sample records, alongside a summary of collected records. A sample is not the whole backend database.', 'The model answers from translated_records and summary. Empty fields are reported as unavailable, not converted into business conclusions.', 'connector adapter · run_api_query:363–440; runner.py:2359–2362');
  const finish = (description, source) => S('Present the result', 'output', 'SDK STATE → UI', 'FRONTEND PROJECTION', description, 'stream.messages → chat\nstream.values.files → file panel\nstream.values.todos → task panel', 'The frontend renders graph messages and state. Tool-call results are matched by tool_call_id; file previews and downloads use separate UI components.', 'The user can ask a follow-up in the same thread. The next model invocation uses the updated conversation and state.', source);
  const cases = {
    news: { title:'Internal news brief', support:'ON-DEMAND SOURCES', request:'Summarize the available internal notices. Preserve dates and flag what may be missing.', context:'The source agent can assemble an internal brief from uploaded or curated documents. Its tool registry does not contain a continuously refreshed news feed or publication scheduler.', boundary:'News ingestion, freshness monitoring, and scheduled delivery are extension points. The implemented search ranks lexical metadata; it is not a vector / BM25 / RRF pipeline.', output:'A source-linked brief with dates supported by the documents, or a clear no-evidence response. “Latest” cannot be established from a search score or file modification time.', options:[['normal','Relevant indexed notice'],['alternate','No useful knowledge match']], paths:{ normal:[S('Select metadata search','model','MODEL → TOOL','REGISTERED TOOL','The model chooses the uploaded-file or curated-knowledge search according to where the user’s notices live. This branch uses the curated knowledge index.','knowledge_search({\n  query: "internal operational notices",\n  limit: 6\n})','Candidates contain title, category, summary, source format, knowledge_path, and match reasons. No full document has entered context yet.','Read a returned candidate whose metadata fits the question. Verify dates in the document rather than assuming a live feed.','runner.py:1921–1949,2345–2355'),S('Read a selected notice','disk','MODEL → TOOL','REGISTERED READER','The chosen knowledge_path points to a generated Markdown record, even if the original notice was a PDF or Word document.','knowledge_document_reader({\n  knowledge_path: "/knowledge/notice.md"\n})','The reader returns source content that can support a dated summary. A candidate may still be old, irrelevant, or incomplete.','If the notice answers the request, summarize and cite its source. If weak, reformulate the search or filter by category/format.','runner.py:1817–1886,2350–2353'),S('Check whether “latest” is supported','model','MODEL → NEXT ACTION','SOURCE-BOUND CHOICE','This example finds enough content for a brief but no evidence of a complete real-time news feed.','Observable choice:\nAnswer from the retrieved notice;\nqualify freshness and missing coverage.','A visible publication date can be cited. The tool does not prove that no newer notice exists elsewhere.','Produce an on-demand brief and state the coverage limit. Do not imply that ingestion or scheduling has run.','runner.py:2352–2354; actual registered tool list:2292–2311'),finish('The chat receives an AI message containing the brief and source paths. A longer brief may instead be written as a root state file.','useChat.ts:336–343; ChatInterface.tsx:436–533')], alternate:[S('Search returns no candidates','disk','KNOWLEDGE SEARCH → MODEL','TOOL OBSERVATION','The metadata index has no useful match for the requested notices.','knowledge_search({query: "current internal notices"})\n→ {status: "ok", candidate_count: 0, candidates: []}','An empty successful search is not a network error and not evidence of no business activity.','The prompt directs the model to try more precise terms or supported category/format filters.','runner.py:2349–2354; knowledge_retrieval.py:165–194'),S('Refine the query','model','MODEL → TOOL','REPLANNING EXAMPLE','The observation changes the next call: reformulate the topic rather than re-read the entire corpus.','knowledge_search({\n  query: "operations bulletin",\n  source_formats: ["PDF"]\n})','This alternate trace still has no relevant supporting document. There is no configured live-news fallback.','Stop the evidence search and record a knowledge miss. This branch illustrates prompt-directed behavior, not a fixed retry count.','runner.py:2351–2354'),S('Record the evidence gap','disk','MODEL → TOOL','REGISTERED AUDIT TOOL','The prompt directs knowledge failures to a miss log instead of unsupported content generation.','record_knowledge_no_hit({\n  question: "Summarize the current internal notices",\n  keywords: ["operations bulletin"]\n})','The tool appends a knowledge_no_hit audit record. It does not create missing source material or add an ingestion job.','Tell the user the available knowledge cannot answer and needs enrichment.','runner.py:1779–1813,2353–2354')]}},
    report:{title:'Report → PDF',support:'IMPLEMENTED PATH',request:'Use the uploaded material to write a detailed report. Let me review it and download a PDF.',context:'The agent creates Markdown through framework file tools. The browser owns preview and export; the server converter owns PDF / DOCX rendering.',boundary:'The export route converts browser-supplied content. It is not an LLM tool, an artifact-ID authorization gateway, or a claim that a generated report is independently fact-checked.',output:'A root-state Markdown report appears in the file panel. A user export returns PDF/DOCX bytes, or an explicit conversion error while preserving the Markdown.',options:[['normal','PDF engine available'],['alternate','PDF engine unavailable']],paths:{normal:[searchUpload,readUpload,planReport,finalReport,requestExport,exportSuccess],alternate:[searchUpload,readUpload,finalReport,requestExport,exportFailure]}},
    word:{title:'Uploaded Word',support:'IMPLEMENTED PATH',request:'Review this uploaded Word draft. Summarize its sections and inspect the table structure where needed.',context:'Upload processing and agent reading are separate. The upload service extracts and indexes once; the model later decides how much detail to read.',boundary:'word_reader extracts content and formatting metadata without modifying the original binary. A generated revision can be exported to a new DOCX; tracked edits and layout-perfect round trips are not established here.',output:'A summary or revised Markdown document, optionally exported as a new Word file. The source Word upload remains a separate disk artifact.',options:[['normal','Summary from existing sidecar'],['alternate','Need formatting / truncated blocks']],paths:{normal:[uploadWord,indexWord,wordSearch,readUpload,finish('The model summarizes the extracted content in chat or writes a new graph-state Markdown file. The file viewer can export that content as DOCX.','runner.py:1003–1042; FileViewDialog.tsx:98–110')],alternate:[uploadWord,indexWord,wordSearch,wordDetails,wordRetry]}},
    voice:{title:'Voice interaction',support:'TWO DISTINCT PATHS',request:'Turn my voice into an editable request, or turn an uploaded meeting recording into structured minutes.',context:'Dictation is a frontend ASR route before the agent runs. A stored recording can instead enter the agent’s workspace, then a named subagent refines its transcript.',boundary:'There is no implemented TTS response or live full-duplex voice loop in these paths. ASR output is not guaranteed correct; reviewed text and source-faithful minutes remain distinct user experiences.',output:'Dictation fills the editable composer. Meeting processing produces a refined transcript and minutes that can be shown in chat or saved as report content.',options:[['normal','Voice input → editable composer'],['alternate','Meeting file → delegated minutes'],['failure','No speech recognized']],paths:{normal:[voiceInput,voiceASR,voiceSubmit,searchUpload],alternate:[S('Upload a meeting recording','disk','USER → UPLOAD SERVICE','PHYSICAL WORKSPACE','The workspace upload route stores the original recording and may create an ASR sidecar during enrichment.','POST /api/workspace\nfile: meeting.m4a','Original audio and extracted transcript are disk resources, separate from graph-state output files.','The agent searches the uploaded material and reads its returned text_path, or transcribes if needed.','api/workspace/route.ts:69–125; uploadEnrichment.ts'),meetingRead,meetingDelegate,finalReport],failure:[voiceInput,S('ASR finds no clear speech','output','VOICE API → UI','ERROR RESPONSE','The route has no usable transcript and returns no_speech rather than creating an empty agent run.','HTTP 422\n{ "error_code": "no_speech",\n  "error": "No clear speech recognized" }\n// Message translated for this exhibit.','The UI shows an error and resets the voice-input state. There is no model tool call to retry.','The user can record again or type the request. The next attempt is an explicit UI action.','api/asr/route.ts:96–100; ChatInterface.tsx:191–246')]}},
    data:{title:'Data read / write',support:'READ TOOLS / WRITE GAP',request:'Count matching records in the connected dataset. If a record needs correction, show how a write would be handled.',context:'The inspected data tools discover, search, and aggregate a dataset HTTP service. They do not expose a SQL connection or a business-record mutation function.',boundary:'No INSERT / UPDATE / DELETE business-data tool is registered. Workspace file edits are not database writes. A write adapter with policy, approval, idempotency and reconciliation is a proposed extension, not a shipped guarantee.',output:'A result grounded in returned dataset records or aggregates. A correction request stops at the missing write capability; the exhibit does not pretend a database row was changed.',options:[['normal','Read an exact aggregate'],['alternate','Request a business-data change'],['failure','Service returns a filter error']],paths:{normal:[dataMeta,dataAggregate,finish('The model reports the returned aggregate with its scope. If rows are sampled or paginated, the response must not mistake the visible page for a full dataset total.','runner.py:2086–2160,2363–2364')],alternate:[dataMeta,S('Discover the write boundary','model','MODEL → CAPABILITY CHECK','UNIMPLEMENTED EXTENSION','A user asks to correct a record, but the registry exposes only meta, search, and aggregate for this dataset.','Registered data tools:\ndataset_api_meta\ndataset_api_search\ndataset_api_aggregate\n\nBusiness mutation tool: not registered','There is no supported mutation call to select. A generated SQL snippet or a file edit would not execute the requested business update.','This example explains the capability gap and asks for an approved write integration. It does not claim an implemented approval workflow.','runner.py:2292–2311'),S('Define a future write contract','output','ARCHITECTURE EXTENSION','NOT IMPLEMENTED IN SOURCE','A future mutation adapter would need an explicit field schema, target authorization, a reviewed effect, and a receipt to establish what happened.','Proposed extension only:\nvalidate → authorize → approve if required\n→ idempotent write → receipt / reconcile','None of these proposed write stages is a source-backed execution trace for the current registry.','Keep the existing query result available and route the correction through an actual authorized business process.','Boundary inferred from actual all_tools registration')],failure:[dataMeta,dataAggregate,S('Inspect the returned error','model','TOOL RESULT → MODEL','REPLANNING EXAMPLE','The wrapper returns status:error and request details on an HTTP failure. The model can use that observation to revise a mistaken filter.','{ "status": "error",\n  "status_code": 400,\n  "request_payload": {"filters": {"unknown_field": "…"}}\n}\n// Partial illustrative error payload.','A failed call has produced an observation, not an answer. The UI may display the tool call as completed because its response arrived.','Inspect metadata and fix the field name, or ask the user to clarify. No universal retry/backoff policy is configured by this wrapper.','runner.py:2135–2154; ChatInterface.tsx:497–513')]}},
    api:{title:'Business API',support:'IMPLEMENTED CONNECTOR',request:'Find maintenance records for an asset using the available business API, and explain any missing fields.',context:'The model chooses a registered connector tool. Inside smart_query, catalog scoring, filter extraction, token handling, pagination, and result normalization are ordinary adapter code.',boundary:'connector.catalog / query / smart_query are public display aliases for the source connector functions. Endpoint names, credentials and domain records are omitted. A token refresh retry is not a general retry policy for arbitrary effects.',output:'A readable answer from translated fields and a bounded result summary. Unsupported queries or unavailable fields are reported explicitly.',options:[['normal','Supported catalog match'],['alternate','Token expires during request'],['failure','No matching business API']],paths:{normal:[apiChoose,apiRoute,apiResult,finish('The model translates the normalized tool observation into a user-facing answer. Raw field dumps are avoided by prompt guidance, not a proxy redaction layer.','runner.py:2359–2362; ChatInterface.tsx:436–513')],alternate:[apiChoose,apiRoute,S('Refresh token once','service','CONNECTOR → AUTH SERVICE','CODED RETRY','The business response returns the adapter’s recognized token-expiry code. The connector obtains a fresh token and repeats the same query once.','call_api(query)\n  → recognized recognized token-authentication response\n  → get_token(force=true)\n  → retry the same query once','This retry happens inside the connector before the tool result reaches the model. It is different from model-driven replanning.','Return the final connector result or its failure. Do not imply unlimited retries or provider-wide exactly-once effects.','connector adapter · call_api:131–140'),apiResult],failure:[apiChoose,S('Return catalog miss','service','CONNECTOR → MODEL','TOOL OBSERVATION','No catalog entry scores as a suitable match for the natural-language question. The adapter returns a structured failure before calling a business endpoint.','{ "success": false,\n  "api_code": null,\n  "records": [],\n  "error_message": "No matching API"\n}\n// Partial translated example.','There is no chosen API. This differs from a valid query that returns zero business records.','The model may call connector.catalog with a clearer topic or ask the user for the asset/query type. This is an example next choice, not an automatic fallback.','connector adapter · run_smart_query:454–466'),S('Choose discovery or clarification','model','MODEL → TOOL / USER','REPLANNING EXAMPLE','The model has a concrete observation: the first tool could not map the request. It can inspect supported capabilities before retrying with a known code.','connector.catalog({query: "maintenance"})\n// Public alias; alternatively ask the user\n// to clarify the asset and required data.','A discovered schema can support a later connector.query call. If no suitable capability exists, the answer should say so.','Select a supported query with explicit filters, or stop without inventing an API result.','runner.py:2164–2190')]} }
  };
  let active = 'news';
  let path = 'normal';
  let position = 0;
  const tabs = [...root.querySelectorAll('[data-case]')];
  const sequence = () => cases[active].paths[path];
  function render() {
    const model = cases[active];
    const trace = sequence();
    const current = trace[position];
    $('step-count').textContent = `${position + 1} / ${trace.length}`;
    $('steps').replaceChildren(...trace.map((item, index) => {
      const button = document.createElement('button');
      button.type = 'button'; button.className = 'case-trace-button'; button.dataset.caseStep = String(index); button.setAttribute('aria-pressed', String(index === position));
      const number = document.createElement('span'); number.textContent = String(index + 1).padStart(2, '0');
      const labels = document.createElement('div'); const title = document.createElement('strong'); title.textContent = item.title; const actor = document.createElement('small'); actor.textContent = item.actor;
      labels.append(title, actor); button.append(number, labels); return button;
    }));
    root.querySelectorAll('[data-case-layer]').forEach((node) => node.classList.toggle('is-active', node.dataset.caseLayer === current.layer));
    $('actor').textContent = current.actor; $('action-type').textContent = current.kind; $('step-title').textContent = current.title; $('step-description').textContent = current.description;
    $('call').textContent = current.call; $('observation-text').textContent = current.observation; $('decision-text').textContent = current.next; $('source').textContent = current.source;
    $('decision-kind').textContent = current.kind.includes('EXTENSION') ? 'PROPOSED NEXT STEP' : 'NEXT OBSERVABLE CHOICE';
    $('prev').disabled = position === 0; $('next').disabled = position === trace.length - 1;
    $('status').textContent = `${model.title} · ${model.options.find(([key]) => key === path)[1]} · action ${position + 1} of ${trace.length}: ${current.title}.`;
  }
  function activate(id, focus = false) {
    active = id; path = 'normal'; position = 0;
    const model = cases[id];
    tabs.forEach((tab) => { const selected = tab.dataset.case === id; tab.setAttribute('aria-selected', String(selected)); tab.tabIndex = selected ? 0 : -1; });
    $('panel').setAttribute('aria-labelledby', `case-tab-${id}`);
    $('request-text').textContent = model.request; $('support').textContent = model.support; $('context-text').textContent = model.context; $('boundary-text').textContent = model.boundary; $('output-text').textContent = model.output;
    $('path').replaceChildren(...model.options.map(([value, label]) => { const option = document.createElement('option'); option.value = value; option.textContent = label; return option; }));
    render();
    if (focus) document.getElementById(`case-tab-${id}`).focus();
  }
  root.addEventListener('click', (event) => {
    const tab = event.target.closest('[data-case]'); if (tab) { activate(tab.dataset.case); return; }
    const action = event.target.closest('[data-case-step]'); if (action) { position = Number(action.dataset.caseStep); render(); return; }
    if (event.target.closest('#case-next') && position < sequence().length - 1) { position += 1; render(); }
    if (event.target.closest('#case-prev') && position > 0) { position -= 1; render(); }
  });
  $('path').addEventListener('change', (event) => { path = event.target.value; position = 0; render(); });
  root.addEventListener('keydown', (event) => {
    if (!event.target.closest('[data-case]')) return;
    const ids = Object.keys(cases); const index = ids.indexOf(active); let next;
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % ids.length;
    if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') next = (index + ids.length - 1) % ids.length;
    if (event.key === 'Home') next = 0;
    if (event.key === 'End') next = ids.length - 1;
    if (next !== undefined) { event.preventDefault(); activate(ids[next], true); }
  });
  activate('news');
})();
